class Tree:
 def __init__(self,maxdepth=5,minleaf=2,mtry=None,rng=None):self.md=maxdepth;self.ml=minleaf;self.mtry=mtry;self.rng=rng or random.Random(0)
 def fit(self,X,y):self.nodes=[];self.root=self.build(X,y,0);return self
 def build(self,X,y,dep):
  vals,cnt=np.unique(y,return_counts=True);node=len(self.nodes);self.nodes.append(None)
  if dep>=self.md or len(y)<2*self.ml or len(vals)==1:pred=vals[np.argmax(cnt)];self.nodes[node]=('leaf',pred);return node
  fs=list(range(X.shape[1]));
  if self.mtry:fs=self.rng.sample(fs,self.mtry)
  best=None
  for f in fs:
   for t in np.unique(X[:,f])[:-1]:
    mask=X[:,f]<=t;n1=mask.sum();n2=len(y)-n1
    if n1<self.ml or n2<self.ml:continue
    score=0
    for m in [mask,~mask]:
     _,co=np.unique(y[m],return_counts=True);score+=len(co) and (m.sum()*(1-np.sum((co/co.sum())**2)))
    if best is None or score<best[0]:best=(score,f,t,mask)
  if best is None:self.nodes[node]=('leaf',vals[np.argmax(cnt)]);return node
  _,f,t,m=best;l=self.build(X[m],y[m],dep+1);rr=self.build(X[~m],y[~m],dep+1);self.nodes[node]=('split',f,t,l,rr);return node
 def predone(self,x):
  n=self.root
  while self.nodes[n][0]=='split':
   _,f,t,l,r=self.nodes[n];n=l if x[f]<=t else r
  return self.nodes[n][1]
