def rf_pred(Xtr,ytr,Xte,depth=5,mtry=4,n=100,seed=1):
 rng=random.Random(seed);votes=np.zeros((len(Xte),3))
 for b in range(n):
  inds=[rng.randrange(len(ytr)) for _ in range(len(ytr))]
  t=Tree(depth,2,mtry,rng).fit(Xtr[inds],ytr[inds])
  for i,x in enumerate(Xte):votes[i,t.predone(x)]+=1
 return votes.argmax(1),votes
